const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf8', 0, buf.length);
// Find all CREATE TABLE statements
const matches = [...str.matchAll(/CREATE TABLE[^)]+\)/gi)];
const tableNames = matches.map(m => {
  const n = m[0].match(/CREATE TABLE \"?(\w+)\"?/i);
  return n ? n[1] : null;
}).filter(Boolean);
const unique = [...new Set(tableNames)];
console.log('All tables:', unique.join(', '));
"

